// ==UserScript==
// @name         FE - Certification of Conformance
// @namespace    https://bristow-scripts.github.io/bristow-scripts
// @version      5.4
// @description  Adds a Print Order Report button on Order Edit that builds a client-side ESTIMATE HTML (from Order_Report.mrt) and prints it - does NOT use server ReportGenerator
// @match        https://liquid-264-drc0bgd0eje0ckcg.westus3-01.azurewebsites.net/Orders/Orders/Edit*
// @updateURL    https://raw.githubusercontent.com/Bristow-Scripts/bristow-scripts/main/FE---Certification-of-Conformance.user.js
// @downloadURL  https://raw.githubusercontent.com/Bristow-Scripts/bristow-scripts/main/FE---Certification-of-Conformance.user.js
// @grant        none
// @require      https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js
// @tag          LIB
// ==/UserScript==

(function () {
    'use strict';

    var BTN_ID = 'print-order-report-btn';
    var LOGO_B64 = '';

    var MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function nl2br(s) {
        return esc(s).replace(/\r\n|\n|\r/g, '<br>');
    }

    function fmtDate(d) {
        if (!d) return '';
        if (typeof d === 'string') {
            var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d);
            if (m) return m[3] + '-' + MONTHS[parseInt(m[2], 10) - 1] + '-' + m[1];
            return d;
        }
        if (d instanceof Date && !isNaN(d)) {
            return String(d.getDate()).padStart(2, '0') + '-' + MONTHS[d.getMonth()] + '-' + d.getFullYear();
        }
        return '';
    }

    function parseMoney(v) {
        if (v == null || v === '') return 0;
        var s = String(v).replace(/[^0-9.\-]/g, '');
        var n = parseFloat(s);
        return isNaN(n) ? 0 : n;
    }

    function fmtMoney(n) {
        if (n == null || isNaN(n)) return '';
        var neg = n < 0;
        var abs = Math.abs(n);
        var fixed = abs.toFixed(2);
        var parts = fixed.split('.');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
        return (neg ? '-' : '') + parts[0] + '.' + parts[1];
    }

    function valOf(el) {
        if (!el) return '';
        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT') {
            return String(el.value || '').trim();
        }
        return String(el.textContent || '').trim();
    }

    function byId(id) {
        return document.getElementById(id);
    }

    function findByLabel(labelPatterns, fallbackId) {
        if (!labelPatterns || !labelPatterns.length) {
            return fallbackId ? document.getElementById(fallbackId) : null;
        }
        var labels = document.querySelectorAll('label.control-label, label[for]');
        for (var i = 0; i < labels.length; i++) {
            var text = (labels[i].textContent || '').trim();
            for (var j = 0; j < labelPatterns.length; j++) {
                if (text.indexOf(labelPatterns[j]) !== -1) {
                    var scope = labels[i].closest('tr') || labels[i].closest('.form-group') || labels[i].parentNode;
                    if (!scope) continue;
                    var inp = scope.querySelector('input.form-control, textarea, select, input[type="text"], input[type="hidden"], .k-picker');
                    if (inp) return inp;
                    var forId = labels[i].getAttribute('for');
                    if (forId) {
                        var byFor = document.getElementById(forId);
                        if (byFor) return byFor;
                    }
                }
            }
        }
        return fallbackId ? document.getElementById(fallbackId) : null;
    }

    function pickerText(el) {
        if (!el) return '';
        if ((el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') && el.value) {
            return String(el.value).trim();
        }
        var row = el.closest('tr') || el.closest('.form-group') || el.parentNode;
        if (row) {
            var kt = row.querySelector('.k-input-value-text, .k-picker-text, .k-readonly');
            if (kt && kt.textContent.trim()) return kt.textContent.trim();
            var anySpan = row.querySelector('td span');
            if (anySpan && anySpan.textContent.trim() && anySpan.textContent.trim() !== '*') {
                return anySpan.textContent.trim();
            }
        }
        try {
            if (window.jQuery) {
                var dd = jQuery(el).data('kendoDropDownList');
                if (dd && dd.text) {
                    var t = dd.text();
                    if (t) return String(t).trim();
                }
                var cb = jQuery(el).data('kendoComboBox');
                if (cb && cb.text) {
                    var t2 = cb.text();
                    if (t2) return String(t2).trim();
                }
            }
        } catch (e) {}
        return String(el.value || '').trim();
    }

    function thValue(labelText) {
        if (!labelText) return '';
        var ths = document.querySelectorAll('th');
        for (var i = 0; i < ths.length; i++) {
            var th = ths[i];
            var t = (th.textContent || '').replace(/\s+/g, ' ').trim();
            if (t.indexOf(labelText) === -1) continue;
            var td = th.nextElementSibling;
            if (!td) continue;
            var cloneT = td.cloneNode(true);
            var scT = cloneT.querySelectorAll('script');
            for (var ti = 0; ti < scT.length; ti++) scT[ti].parentNode.removeChild(scT[ti]);
            var dkT = cloneT.querySelectorAll('.text-danger');
            for (var tj = 0; tj < dkT.length; tj++) dkT[tj].parentNode.removeChild(dkT[tj]);
            var mail = cloneT.querySelector('a[href^="mailto:"]');
            if (mail && (mail.textContent || '').trim()) return mail.textContent.trim();
            var kvt = cloneT.querySelector('.k-input-value-text');
            if (kvt) {
                var ktt = (kvt.textContent || '').replace(/\s+/g, ' ').trim();
                if (ktt && ktt !== '*') return ktt;
                continue;
            }
            var linked = cloneT.querySelector('span a, a');
            if (linked && (linked.textContent || '').trim()) return linked.textContent.trim();
            var span = cloneT.querySelector('span:not(.text-danger)');
            if (span && (span.textContent || '').trim() && span.textContent.trim() !== '*') {
                return span.textContent.trim();
            }
            var txt = (cloneT.innerText || cloneT.textContent || '').replace(/\s+/g, ' ').trim();
            if (txt && txt !== '*' && txt.indexOf('kendo.syncReady') === -1 && txt.indexOf('kendoDropDownList') === -1) {
                return txt;
            }
        }
        return '';
    }

    function valueAfterLabel(labelPatterns) {
        if (!labelPatterns || !labelPatterns.length) return '';
        var labels = document.querySelectorAll('label.control-label, label[for]');
        for (var i = 0; i < labels.length; i++) {
            var text = (labels[i].textContent || '').trim();
            for (var j = 0; j < labelPatterns.length; j++) {
                if (text.indexOf(labelPatterns[j]) === -1) continue;
                var cell = labels[i].closest('td') || labels[i].closest('th') || labels[i].parentNode;
                if (!cell) continue;
                var next = cell.nextElementSibling;
                if (!next) continue;
                var kvt = next.querySelector('.k-input-value-text');
                if (kvt) {
                    var ktt = (kvt.textContent || '').replace(/\s+/g, ' ').trim();
                    if (ktt && ktt !== '*') return ktt;
                    continue;
                }
                if (next.querySelector('script')) continue;
                var mail = next.querySelector('a[href^="mailto:"]');
                if (mail && (mail.textContent || '').trim()) return mail.textContent.trim();
                var span = next.querySelector('span:not(.text-danger)');
                if (span) {
                    var st = (span.textContent || '').replace(/\s+/g, ' ').trim();
                    if (st && st !== '*') return st;
                }
                var inp = next.querySelector('input:not([type="hidden"]):not([disabled]), textarea, select');
                if (inp && inp.value) return String(inp.value).trim();
                var hiddenInp = next.querySelector('input[type="hidden"][id*="OptionId"], input[id*="OptionId"]');
                if (hiddenInp && hiddenInp.value && hiddenInp.value.trim()) {
                    try {
                        if (window.jQuery) {
                            var dd = jQuery(hiddenInp).data('kendoDropDownList');
                            if (dd && dd.text && dd.text().trim()) return String(dd.text()).trim();
                        }
                    } catch (e) {}
                }
                var clone = next.cloneNode(true);
                var scripts = clone.querySelectorAll('script');
                for (var si = 0; si < scripts.length; si++) scripts[si].parentNode.removeChild(scripts[si]);
                var dangers = clone.querySelectorAll('.text-danger');
                for (var di = 0; di < dangers.length; di++) dangers[di].parentNode.removeChild(dangers[di]);
                var txt = (clone.innerText || clone.textContent || '').replace(/\s+/g, ' ').trim();
                if (txt && txt !== '*' && txt.indexOf('kendo.syncReady') === -1 && txt.indexOf('kendoDropDownList') === -1) {
                    return txt;
                }
                continue;
            }
        }
        return '';
    }

    function kendoTextNear(el) {
        if (!el) return '';
        var scope = el.closest('td') || el.closest('.k-picker') || el.parentNode;
        if (!scope) return '';
        var kvt = scope.querySelector ? scope.querySelector('.k-input-value-text') : null;
        if (kvt) {
            var t = (kvt.textContent || '').replace(/\s+/g, ' ').trim();
            if (t && t !== '*') return t;
        }
        try {
            if (window.jQuery) {
                var dd = jQuery(el).data('kendoDropDownList');
                if (dd && dd.text) {
                    var dt = String(dd.text() || '').trim();
                    if (dt) return dt;
                }
            }
        } catch (e) {}
        return '';
    }

    function workPerformedValue() {
        var lbl = document.querySelector('label[for="OrderHead_CustomFields_10__Label"]')
            || document.querySelector('label.control-label');
        var labels = document.querySelectorAll('label.control-label, label[for]');
        for (var i = 0; i < labels.length; i++) {
            var text = (labels[i].textContent || '').replace(/\s+/g, ' ').trim();
            if (text.indexOf('Work Performed') !== -1) {
                lbl = labels[i];
                break;
            }
        }
        if (lbl) {
            var cell = lbl.closest('th') || lbl.closest('td') || lbl.parentNode;
            var next = cell && cell.nextElementSibling;
            if (next) {
                var kvt = next.querySelector('.k-input-value-text');
                if (kvt) {
                    var t = (kvt.textContent || '').replace(/\s+/g, ' ').trim();
                    return (t && t !== '*') ? t : '';
                }
                var cloneW = next.cloneNode(true);
                var scW = cloneW.querySelectorAll('script');
                for (var wi = 0; wi < scW.length; wi++) scW[wi].parentNode.removeChild(scW[wi]);
                var dkW = cloneW.querySelectorAll('.text-danger');
                for (var wj = 0; wj < dkW.length; wj++) dkW[wj].parentNode.removeChild(dkW[wj]);
                var tw = (cloneW.innerText || cloneW.textContent || '').replace(/\s+/g, ' ').trim();
                if (tw && tw !== '*' && tw.indexOf('kendo.syncReady') === -1 && tw.indexOf('kendoDropDownList') === -1) {
                    return tw;
                }
                return '';
            }
        }
        var opt = byId('OrderHead_CustomFields_10__OptionId');
        if (opt) {
            var pick = opt.closest('.k-picker');
            if (pick) {
                var kvt2 = pick.querySelector('.k-input-value-text');
                if (kvt2) {
                    var t2 = (kvt2.textContent || '').replace(/\s+/g, ' ').trim();
                    return (t2 && t2 !== '*') ? t2 : '';
                }
            }
            var kt = kendoTextNear(opt);
            if (kt && kt.indexOf('kendo') === -1) return kt;
            var tdOpt = opt.closest('td');
            if (tdOpt) {
                var cloneO = tdOpt.cloneNode(true);
                var scO = cloneO.querySelectorAll('script');
                for (var oi = 0; oi < scO.length; oi++) scO[oi].parentNode.removeChild(scO[oi]);
                var to = (cloneO.innerText || cloneO.textContent || '').replace(/\s+/g, ' ').trim();
                if (to && to !== '*' && to.indexOf('kendo.syncReady') === -1 && to.indexOf('kendoDropDownList') === -1) {
                    return to;
                }
            }
            return '';
        }
        return '';
    }

    function fieldByValmsg(fieldPath) {
        if (!fieldPath) return '';
        var el = document.querySelector('[data-valmsg-for="' + fieldPath + '"]');
        if (!el) return '';
        var td = el.closest('td');
        if (!td) return '';
        var clone = td.cloneNode(true);
        var scripts = clone.querySelectorAll('script');
        for (var i = 0; i < scripts.length; i++) scripts[i].parentNode.removeChild(scripts[i]);
        var dangers = clone.querySelectorAll('.text-danger');
        for (var j = 0; j < dangers.length; j++) dangers[j].parentNode.removeChild(dangers[j]);
        var mail = clone.querySelector('a[href^="mailto:"]');
        if (mail && (mail.textContent || '').trim()) return mail.textContent.trim();
        var kvt = clone.querySelector('.k-input-value-text');
        if (kvt) {
            var kt = (kvt.textContent || '').replace(/\s+/g, ' ').trim();
            if (kt && kt !== '*') return kt;
        }
        var span = clone.querySelector('span');
        if (span && (span.textContent || '').trim() && span.textContent.trim() !== '*') {
            return (span.textContent || '').trim();
        }
        var txt = (clone.innerText || clone.textContent || '').trim();
        if (txt && txt !== '*') return txt;
        return '';
    }

    function collectOrderData() {
        var d = {
            orderNumber: '',
            date: fmtDate(new Date()),
            customerPO: '',
            customer: '',
            contactName: '',
            phone: '',
            email: '',
            ship1: '',
            shipCity: '',
            shipPostal: '',
            shipProvince: '',
            customerSnag: '',
            internalSnag: '',
            comments: '',
            workLevel: '',
            componentName: '',
            serialNumber: '',
            lines: [],
            subtotal: 0
        };

        var on = '';
        var candidates = [
            byId('OrderHead_OrderNumber'),
            byId('Order_Number'),
            document.querySelector('.sticky h2, .sticky h3, .sticky .lead'),
            document.querySelector('h2 small, h3 small'),
            document.querySelector('#HeaderTarget h2, #HeaderTarget h3')
        ];
        for (var i = 0; i < candidates.length; i++) {
            var t = valOf(candidates[i]);
            if (t) {
                var mm = t.match(/OC-[A-Za-z]+-\d+/);
                if (mm) { on = mm[0]; break; }
            }
        }
        if (!on) {
            var body = document.body ? document.body.innerText : '';
            var m2 = /\bOC-[A-Z]{3}-\d{5,}\b/.exec(body);
            if (m2) on = m2[0];
        }
        if (!on) {
            var m3 = (document.title || '').match(/OC-[A-Z]{3}-\d+/);
            if (m3) on = m3[0];
        }
        d.orderNumber = on;

        d.customer = fieldByValmsg('OrderHead.CustomerId')
            || thValue('Company')
            || (function () {
                var a = byId('customerCompanyName');
                if (a && (a.textContent || '').trim()) return a.textContent.trim();
                return pickerText(findByLabel(['Company', 'Customer'], 'OrderHead_CustomerId'));
            })();
        d.contactName = thValue('Primary Contact')
            || (function () {
                var cEl = byId('OrderHead_CustomerContactId');
                if (cEl) {
                    var cRow = cEl.closest('tr');
                    if (cRow) {
                        var a = cRow.querySelector('td a, td span');
                        if (a && (a.textContent || '').trim()) return a.textContent.trim();
                    }
                }
                return pickerText(findByLabel(['Contact'], 'OrderHead_CustomerContactId'));
            })();

        d.phone = thValue('Phone')
            || valOf(findByLabel(['Phone'], null) || byId('OrderHead_ContactPhone') || byId('ContactPhone'));
        d.email = thValue('Email')
            || valOf(findByLabel(['Email'], null) || byId('OrderHead_ContactEmail') || byId('ContactEmail'));

        d.ship1 = fieldByValmsg('OrderHead.ShippingAddress1')
            || valOf(findByLabel(['Shipping Address', 'Ship Address', 'Address 1'], 'OrderHead_ShippingAddress1'))
            || valOf(byId('OrderHead_ShippingAddress1') || byId('ShippingAddress1'));
        d.shipCity = fieldByValmsg('OrderHead.ShippingCity')
            || valOf(findByLabel(['Shipping City', 'Ship City', 'City'], 'OrderHead_ShippingCity'))
            || valOf(byId('OrderHead_ShippingCity') || byId('ShippingCity'));
        d.shipProvince = fieldByValmsg('OrderHead.ShippingProvince')
            || valOf(findByLabel(['Shipping Province', 'Ship Province', 'Province', 'State'], 'OrderHead_ShippingProvince'))
            || valOf(byId('OrderHead_ShippingProvince') || byId('ShippingProvince'));
        d.shipPostal = fieldByValmsg('OrderHead.ShippingPostalCode')
            || valOf(findByLabel(['Shipping Postal', 'Ship Postal', 'Postal', 'Zip'], 'OrderHead_ShippingPostalCode'))
            || valOf(byId('OrderHead_ShippingPostalCode') || byId('ShippingPostalCode'));

        d.customerPO = thValue('Customer PO')
            || valOf(findByLabel(['Customer PO', 'PO Number', 'P/O', 'CustomerPO'], 'OrderHead_CustomerPO'))
            || valOf(byId('OrderHead_CustomerPO') || byId('CustomerPO'));

        d.customerSnag = valOf(findByLabel(['Customer Snag'], 'AerospaceHead_CustomerSnag'));
        d.internalSnag = valOf(findByLabel(['Internal Snag', 'Findings'], 'AerospaceHead_InternalSnag'));

        d.comments = fieldByValmsg('OrderHead.CustomerFacingNotes')
            || thValue('Customer Visible Notes')
            || valOf(findByLabel(['Customer Visible', 'Customer Facing', 'Customer Notes', 'Comments'], 'OrderHead_CustomerFacingNotes'));
        if (!d.comments) d.comments = valOf(byId('OrderHead_CustomerFacingNotes') || byId('CustomerFacingNotes'));
        if (!d.comments) {
            var tas = document.querySelectorAll('textarea[id*="Facing"], textarea[id*="Comment"]');
            if (tas.length) d.comments = valOf(tas[0]);
        }

        d.workLevel = workPerformedValue()
            || thValue('Work Performed')
            || valueAfterLabel(['Work Performed']);
        if (d.workLevel && !d.workLevel.replace(/\s/g, '').length) d.workLevel = '';

        d.componentName = valueAfterLabel(['Component']);
        if (!d.componentName) {
            var compInp = byId('AerospaceHead_ComponentId');
            if (compInp) {
                var crow = compInp.closest('tr');
                if (crow) {
                    var cspans = crow.querySelectorAll('td span');
                    for (var ci = 0; ci < cspans.length; ci++) {
                        var ct = cspans[ci].textContent.trim();
                        if (ct && ct !== '*' && !/^\d{4}-\d{2}-\d{2}/.test(ct)) {
                            d.componentName = ct;
                            break;
                        }
                    }
                }
            }
        }
        if (!d.componentName) {
            d.componentName = valOf(findByLabel(['Component Name', 'Part Number'], null));
        }

        d.serialNumber = valueAfterLabel(['Serial Number', 'S/N'])
            || valOf(byId('AerospaceHead_SerialNumber'))
            || valOf(findByLabel(['Serial Number', 'S/N'], null));

        var OMIT_LINE_PATTERNS = [
            'Miscellaneous (MIS)',
            'Labour',
            'Labor',
            'FREIGHT',
            'Shop Supplies'
        ];

        var rows = document.querySelectorAll('tr.line-item[id^="OrderLine_"]');
        var lineNo = 0;
        for (var r = 0; r < rows.length; r++) {
            var row = rows[r];
            var lineId = row.id.replace('OrderLine_', '');
            if (!lineId) continue;

            var desc = '';
            var cardRow = row.querySelector('.lq-flex-card-row');
            if (cardRow) {
                var descSpans = cardRow.querySelectorAll(':scope > span');
                for (var ds = 0; ds < descSpans.length; ds++) {
                    var dst = (descSpans[ds].textContent || '').replace(/\s+/g, ' ').trim();
                    if (dst && !descSpans[ds].classList.contains('bold') && !descSpans[ds].classList.contains('label')) {
                        desc = dst;
                        break;
                    }
                }
                if (!desc) {
                    var plain = cardRow.querySelector('span:not(.label):not(.bold)');
                    if (plain) desc = (plain.textContent || '').replace(/\s+/g, ' ').trim();
                }
            }
            if (!desc) {
                var flex = row.querySelector('.lq-flex-data-container');
                if (flex) {
                    desc = (flex.innerText || flex.textContent || '').replace(/\s+/g, ' ').trim();
                }
            }
            if (!desc) {
                var tds = row.querySelectorAll('td');
                if (tds[1]) desc = (tds[1].innerText || '').replace(/\s+/g, ' ').trim();
            }

            var rowText = (row.innerText || row.textContent || '').replace(/\s+/g, ' ');
            var rowUpper = rowText.toUpperCase();
            var omit = false;
            for (var oi = 0; oi < OMIT_LINE_PATTERNS.length; oi++) {
                if (rowUpper.indexOf(OMIT_LINE_PATTERNS[oi].toUpperCase()) !== -1) {
                    omit = true;
                    break;
                }
            }
            if (omit) continue;

            lineNo++;

            var qtyEl = byId('OrderLineQuantityMask_' + lineId) || byId('OrderLineQuantity_' + lineId);
            var priceEl = byId('OrderLinePriceMask_' + lineId) || byId('OrderLinePrice_' + lineId);
            var subEl = byId('OrderLineSubtotal_' + lineId);

            var qty = parseMoney(valOf(qtyEl));
            var price = parseMoney(valOf(priceEl));
            var sub = parseMoney(valOf(subEl));
            if (!sub && qty && price) sub = qty * price;

            var note = '';
            var noteRow = byId('OrderLineNotes_' + lineId);
            if (noteRow) {
                var nspan = noteRow.querySelector('span');
                note = nspan ? (nspan.textContent || '').trim() : (noteRow.textContent || '').trim();
            }

            if (!desc && !qty && !price && !sub) { lineNo--; continue; }

            var condition = '';
            var condTag = row.querySelector('[data-original-title="Condition"]');
            if (condTag) condition = (condTag.textContent || '').replace(/\s+/g, ' ').trim();
            if (condition === '\u00a0' || condition === ' ') condition = '';

            d.lines.push({
                n: lineNo,
                desc: desc,
                qty: qty,
                price: price,
                sub: sub,
                note: note,
                condition: condition
            });
            d.subtotal += sub;
        }

        if (!d.subtotal) {
            var labs = document.querySelectorAll('td, th, span, div, label');
            for (var li = 0; li < labs.length; li++) {
                if ((labs[li].textContent || '').trim() === 'Subtotal') {
                    var cell = labs[li].parentNode;
                    if (cell) {
                        var next = cell.nextElementSibling || (cell.parentNode && cell.parentNode.children[1]);
                        if (next) {
                            var pv = parseMoney(next.textContent);
                            if (pv) { d.subtotal = pv; break; }
                        }
                    }
                }
            }
        }

        return d;
    }

    function buildEstimateHtml(d) {
        var logoSrc = 'data:image/jpeg;base64,' + LOGO_B64;
        var currency = 'CAD';

        var shipHtml = '';
        if (d.ship1) shipHtml += '<br>' + nl2br(d.ship1);
        var cityProvLine = [d.shipCity, d.shipProvince].filter(Boolean).join(', ');
        if (cityProvLine) shipHtml += '<br>' + esc(cityProvLine);
        if (d.shipPostal) shipHtml += '<br>' + esc(d.shipPostal);

        var CONDITION_OPTIONS = ['', 'AR', 'INS', 'NE', 'NS', 'OH', 'RD', 'RP', 'SV'];

        function condSelect(L) {
            var opts = '';
            for (var ci = 0; ci < CONDITION_OPTIONS.length; ci++) {
                var val = CONDITION_OPTIONS[ci];
                var label = val === '' ? 'Blank' : val;
                var sel = (L.condition || '') === val ? ' selected' : '';
                opts += '<option value="' + esc(val) + '"' + sel + '>' + label + '</option>';
            }
            if (L.condition && CONDITION_OPTIONS.indexOf(L.condition) === -1) {
                opts += '<option value="' + esc(L.condition) + '" selected>' + esc(L.condition) + '</option>';
            }
            return '<select class="cond-sel">' + opts + '</select>';
        }

        var lineRows = '';
        for (var i = 0; i < d.lines.length; i++) {
            var L = d.lines[i];
            lineRows +=
                '<tr class="line">' +
                '<td class="c-num">' + esc(L.n) + '</td>' +
                '<td class="c-desc">' + esc(L.desc) + '</td>' +
                '<td class="c-cond">' + condSelect(L) + '</td>' +
                '<td class="c-qty">' + (L.qty ? esc(String(L.qty).replace(/\.0$/, '')) : '') + '</td>' +
                '</tr>';
            if (L.note) {
                lineRows +=
                    '<tr class="note-row"><td></td><td class="c-note" colspan="3">' + nl2br(L.note) + '</td></tr>';
            }
        }

        var h = '';
        h += '<!DOCTYPE html><html><head><meta charset="utf-8"><title>Certificate of Conformance - ' + esc(d.orderNumber) + '</title><style>';
        h += '@page { size: letter; margin: 1cm; }';
        h += '* { box-sizing: border-box; }';
        h += 'body { font-family: Arial, Helvetica, sans-serif; font-size: 10pt; color: #000; margin: 0; padding: 0; }';
        h += '.page { width: 100%; background: #ffffff; }';
        h += '.hdr { display: flex; align-items: flex-start; gap: 8px; }';
        h += '.hdr-left { flex: 1 1 50%; }';
        h += '.hdr-right { flex: 1 1 50%; }';
        h += '.logo { width: 320px; max-width: 95%; height: auto; display: block; margin-left: auto; }';
        h += '.addr { text-align: center; font-family: "Arial Black", Arial, sans-serif; font-size: 11pt; font-weight: 900; line-height: 1.25; margin-top: 2px; }';
        h += '.estimate-title { text-align: center; font-size: 20pt; font-weight: bold; margin: 0 0 6px 0; }';
        h += '.meta { width: 100%; border-collapse: collapse; }';
        h += '.meta td { padding: 1px 0; vertical-align: top; font-size: 10pt; }';
        h += '.meta .lbl { width: 40%; text-align: right; font-weight: bold; padding-right: 6px; white-space: nowrap; }';
        h += '.meta .val { width: 60%; }';
        h += '.mid { margin-top: 8px; }';
        h += '.row { display: flex; gap: 8px; margin-bottom: 3px; }';
        h += '.lab { font-weight: bold; font-size: 10pt; min-width: 120px; }';
        h += '.lab.right { text-align: right; }';
        h += '.valcol { flex: 1; font-size: 10pt; }';
        h += '.rule { border: none; border-top: 1px solid #ddd; margin: 6px 0; }';
        h += '.boxes { display: flex; gap: 12px; margin-top: 12px; }';
        h += '.box { flex: 1; border: 1px solid #000; }';
        h += '.box-h { background: #f2f2f2; border-bottom: 1px solid #000; text-align: center; font-size: 10pt; padding: 4px; font-weight: bold; }';
        h += '.box-b { text-align: center; font-size: 10pt; padding: 8px 4px; min-height: 24px; }';
        h += '.comments-hdr { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 3px; }';
        h += '.comments-hdr .lab { font-weight: bold; font-size: 10pt; min-width: auto; }';
        h += '.comments-hdr .work { font-size: 10pt; text-align: right; white-space: nowrap; }';
        h += '.comments-body { font-size: 10pt; text-align: left; margin: 0 0 6px 0; }';
        h += 'table.lines { width: 100%; border-collapse: collapse; margin-top: 12px; }';
        h += 'table.lines th { background: #f2f2f2; border: 1px solid #000; padding: 4px 5px; font-size: 9pt; font-weight: bold; text-align: left; }';
        h += 'table.lines th.r { text-align: right; }';
        h += 'table.lines th.c { text-align: center; }';
        h += 'table.lines td { border: 1px solid #000; padding: 4px 5px; font-family: "Courier New", Courier, monospace; font-size: 9pt; vertical-align: middle; background: #fff; }';
        h += 'table.lines td.c-num { text-align: center; width: 6%; }';
        h += 'table.lines td.c-desc { width: 70%; }';
        h += 'table.lines td.c-cond { text-align: center; width: 12%; }';
        h += 'table.lines td.c-qty { text-align: right; width: 12%; }';
        h += '.cond-sel { width: 100%; font-family: "Courier New", Courier, monospace; font-size: 9pt; border: none; background: transparent; text-align: center; }';
        h += '@media print { .cond-sel { -webkit-appearance: none; appearance: none; text-align: center; } }';
        h += 'table.lines tr.note-row td { background: #f2f2f2; }';
        h += '.subtable { width: 100%; border-collapse: collapse; }';
        h += '.subtable td { font-family: "Courier New", Courier, monospace; font-size: 9pt; font-weight: bold; padding: 4px 5px; }';
        h += '.subtable td.lab-sub { width: 75%; text-align: right; border-top: 1px solid #000; border-bottom: 1px solid #000; border-right: none; }';
        h += '.subtable td.amt { width: 12%; text-align: right; border-top: 1px solid #000; border-bottom: 1px solid #000; border-right: none; }';
        h += '.subtable td.cur { width: 13%; text-align: right; border-top: 1px solid #000; border-bottom: 1px solid #000; border-left: none; }';
        h += '.sign { display: flex; gap: 0; margin-top: 16px; }';
        h += '.sign .cell { flex: 1; border: 1px solid #000; padding: 5px 8px; font-size: 9pt; }';
        h += '.sign .cert { font-size: 8pt; line-height: 1.2; margin-bottom: 18px; }';
        h += '@media print { .no-print { display: none !important; } }';
        h += '</style></head><body><div class="page">';

        h += '<div class="hdr">';
        h += '<div class="hdr-left">';
        h += '<img class="logo" src="' + logoSrc + '" alt="BRISTOW">';
        h += '<div class="addr">180 Portage Close<br>Sherwood Park, AB T8H 2R6<br>Ph: 780-416-5500</div>';
        h += '</div>';
        h += '<div class="hdr-right">';
        h += '<div class="estimate-title">Certificate of Conformance</div>';
        h += '<table class="meta">';
        h += '<tr><td class="lbl">Date:</td><td class="val">' + esc(d.date) + '</td></tr>';
        h += '<tr><td class="lbl">WO Number:</td><td class="val">' + esc(d.orderNumber) + '</td></tr>';
        h += '<tr><td class="lbl">PO:</td><td class="val">' + esc(d.customerPO) + '</td></tr>';
        h += '<tr><td class="lbl">Contact:</td><td class="val">' + esc(d.contactName) +
            (d.phone ? '<br>' + esc(d.phone) : '') +
            (d.email ? '<br>' + esc(d.email) : '') +
            '</td></tr>';
        h += '</table></div></div>';

        h += '<div class="mid">';
        h += '<div class="row"><div class="lab">Customer:</div><div class="valcol">' + esc(d.customer) + shipHtml + '</div></div>';
        h += '<hr class="rule">';
        h += '<div class="comments-hdr"><div class="lab">Comments:</div></div>';
        h += '<div class="comments-body">' + nl2br(d.comments) + '</div>';
        h += '</div>';

        h += '<div class="boxes">';
        h += '<div class="box"><div class="box-h">Part Number</div><div class="box-b">' + esc(d.componentName) + '</div></div>';
        h += '<div class="box"><div class="box-h">Serial Number</div><div class="box-b">' + esc(d.serialNumber) + '</div></div>';
        h += '</div>';

        h += '<table class="lines"><thead><tr>';
        h += '<th class="c">Line #</th><th>Description</th><th class="c">Condition</th><th class="r">Quantity</th>';
        h += '</tr></thead><tbody>';
        h += lineRows || '<tr><td class="c-num"></td><td class="c-desc"></td><td class="c-cond"></td><td class="c-qty"></td></tr>';
        h += '</tbody></table>';

        h += '<div class="sign">';
        h += '<div class="cell"><div class="cert">I HEREBY CERTIFY THAT THE AIRCRAFT PARTS DESCRIBED HEREON WERE ACQUIRED FROM A SOURCE OF SUPPLY THAT IS CONSISTENT WITH THE CONDITIONS UNDER WHICH TRANSPORT CANADA DISTRIBUTOR APPROVAL #111-94 HAS BEEN GRANTED.</div></div>';
        h += '<div class="cell"><br>Name:________________________________________<br><br>Date:________________ Signed:___________________</div>';
        h += '</div>';

        h += '</div></body></html>';
        return h;
    }

    function renderEstimate() {
        var d = collectOrderData();
        var html = buildEstimateHtml(d);
        var w = window.open('', '_blank', 'width=1000,height=800');
        if (!w) {
            alert('Please allow popups for this site to print the estimate.');
            return;
        }
        w.document.write(html);
        w.document.close();
        var bar = w.document.createElement('div');
        bar.className = 'no-print';
        bar.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#333;color:#fff;padding:6px 10px;text-align:right;z-index:9999;font-family:Arial,sans-serif;';
        bar.innerHTML = '<span style="float:left;padding-top:4px;font-size:12px;" id="cocPdfStatus">Set Condition, then print</span>' +
            '<button id="cocPrintBtn" style="font-size:14px;padding:4px 16px;cursor:pointer;margin-left:8px;">Print</button>' +
            '<button id="cocPdfBtn" style="font-size:14px;padding:4px 16px;cursor:pointer;margin-left:8px;">Export PDF</button>';
        w.document.body.insertBefore(bar, w.document.body.firstChild);
        var pb = w.document.getElementById('cocPrintBtn');
        if (pb) pb.addEventListener('click', function () { w.print(); });
        var pdfBtn = w.document.getElementById('cocPdfBtn');
        var pdfStatus = w.document.getElementById('cocPdfStatus');
        function setStatus(msg) {
            if (pdfStatus) pdfStatus.textContent = msg;
        }
        function exportDone() {
            pdfBtn.disabled = false;
            pdfBtn.textContent = 'Export PDF';
        }
        if (pdfBtn) pdfBtn.addEventListener('click', function () {
            function fallback(msg) {
                exportDone();
                setStatus(msg || 'PDF failed - use Print / Save as PDF');
            }
            function downloadBlob(blob, fname) {
                var url = w.URL.createObjectURL(blob);
                var a = w.document.createElement('a');
                a.href = url;
                a.download = fname;
                w.document.body.appendChild(a);
                a.click();
                setTimeout(function () {
                    w.URL.revokeObjectURL(url);
                    if (a.parentNode) a.parentNode.removeChild(a);
                }, 4000);
            }
            function runExport() {
                var pageEl = w.document.querySelector('.page');
                if (!pageEl) {
                    fallback('page not found');
                    return;
                }
                var fname = 'Certificate of Conformance' + (d.orderNumber ? ' - ' + d.orderNumber : '') + '.pdf';
                setStatus('Rendering...');
                setTimeout(function () {
                    try {
                        var worker = w.html2pdf().set({
                                margin: 10,
                            filename: fname,
                            image: { type: 'jpeg', quality: 0.96 },
                                html2canvas: {
                                    scale: 2,
                                    useCORS: true,
                                    allowTaint: true,
                                    backgroundColor: '#ffffff',
                                    scrollX: 0,
                                    scrollY: 0,
                                    width: 816,
                                    windowWidth: 816,
                                    windowHeight: Math.max(pageEl.scrollHeight, 1056),
                                    onclone: function (doc) {
                                        var src = doc.querySelector('.page');
                                        if (src) {
                                            src.style.visibility = 'visible';
                                            src.style.opacity = '1';
                                            src.style.display = 'block';
                                            src.style.background = '#ffffff';
                                            src.style.width = '816px';
                                            src.style.maxWidth = '816px';
                                            src.style.margin = '0 auto';
                                            src.style.overflow = 'hidden';
                                        }
                                        var bars = doc.querySelectorAll('.no-print');
                                        for (var bi = 0; bi < bars.length; bi++) bars[bi].style.display = 'none';
                                    }
                                },
                            jsPDF: { unit: 'mm', format: 'letter', orientation: 'portrait' }
                        }).from(pageEl).toPdf();

                        var pdfObj = null;
                        if (typeof worker.get === 'function') {
                            var maybe = worker.get('pdf');
                            if (maybe && typeof maybe.then === 'function') {
                                maybe.then(function (pdf) { pdfObj = pdf; }).catch(function (e) {
                                    fallback('get pdf failed: ' + e);
                                });
                            }
                        }
                        setTimeout(function () {
                            try {
                                if (pdfObj) {
                                    var blob = pdfObj.output('blob');
                                    if (blob && blob.size > 0) {
                                        downloadBlob(blob, fname);
                                        setStatus('Saved: ' + fname);
                                        exportDone();
                                    } else {
                                        fallback('empty pdf');
                                    }
                                } else if (typeof worker.save === 'function') {
                                    worker.save();
                                    setStatus('Save requested');
                                    exportDone();
                                } else {
                                    fallback('no save method');
                                }
                            } catch (e3) {
                                fallback('save error: ' + e3);
                            }
                        }, 2000);
                    } catch (e) {
                        fallback('export error: ' + e);
                    }
                }, 400);
            }
            pdfBtn.disabled = true;
            pdfBtn.textContent = 'Saving...';
            setStatus('Loading PDF library...');
            if (typeof w.html2pdf !== 'undefined') {
                runExport();
                return;
            }
            var lib = w.document.createElement('script');
            lib.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';
            lib.onload = runExport;
            lib.onerror = function () { fallback('library failed to load'); };
            w.document.head.appendChild(lib);
        });
    }

    function injectButton() {
        if (document.getElementById(BTN_ID)) return true;

        var menu = document.querySelector('ul.print-options-button ul.dropdown-menu')
            || document.querySelector('.print-options-button .dropdown-menu');
        if (!menu) return false;

        var li = document.createElement('li');
        li.id = BTN_ID;
        var a = document.createElement('a');
        a.href = '#';
        a.innerHTML = '<span class="glyphicon glyphicon-certificate" aria-hidden="true"></span> Cert. of Conf.';
        a.addEventListener('click', function (ev) {
            ev.preventDefault();
            try {
                renderEstimate();
            } catch (e) {
                console.error('[Cert of Conf]', e);
                alert('Failed to build certificate: ' + e.message);
            }
        });
        li.appendChild(a);
        menu.appendChild(li);
        return true;
    }

    function startInit() {
        var tries = 0;
        var id = setInterval(function () {
            tries++;
            if (injectButton() || tries > 80) clearInterval(id);
        }, 500);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', startInit);
    } else {
        startInit();
    }
})();
